volatile int binarysearch_seed;

struct binarysearch_DATA {
  int key;
  int value;
};

#define binarysearch_N 4096
struct binarysearch_DATA binarysearch_data[ binarysearch_N ];

int binarysearch_result;

void binarysearch_initSeed( void )
{
  binarysearch_seed = 0;
}

long binarysearch_randomInteger( void )
{
  binarysearch_seed = binarysearch_seed * 1103515245u + 12345u;
  return ( ( unsigned )binarysearch_seed >> 16 ) & 0x7fff;
}

void binarysearch_init( void )
{
  int i, key = 0;
  binarysearch_initSeed();
  for ( i = 0; i < binarysearch_N; ++i ) {
    key += 1 + ( binarysearch_randomInteger() & 3 );
    binarysearch_data[ i ].key = key;
    binarysearch_data[ i ].value = binarysearch_randomInteger();
  }
}

int binarysearch_return( void )
{
  return ( binarysearch_result );
}

int binarysearch_binary_search( int x )
{
  int fvalue, mid, up, low;

  low = 0;
  up = binarysearch_N - 1;
  fvalue = -1;

  _Pragma( "loopbound min 1 max 4" )
  while ( low <= up ) {
    mid = ( low + up ) >> 1;

    if ( binarysearch_data[ mid ].key == x ) {

      up = low - 1;
      fvalue = binarysearch_data[ mid ].value;
    } else

      if ( binarysearch_data[ mid ].key > x )

        up = mid - 1;
      else
        low = mid + 1;
  }

  return ( fvalue );
}

void _Pragma( "entrypoint" ) binarysearch_main( void )
{
  int i, sum = 0;
  for ( i = 0; i < 4096; i++ )
    sum += binarysearch_binary_search( binarysearch_randomInteger() & 0x3fff );
  binarysearch_result = sum;
}

