  gsm_enc_Gsm_Short_Term_Analysis_Filter  ( S, LARc, so );

  _Pragma( "loopbound min 4 max 4" )
  for ( k = 0; k <= 3; k++, xMc += 13 ) {

    gsm_enc_Gsm_Long_Term_Predictor (
      so + k * 40,
