)

{

  longword  L_result;
  int   k   ;

  e -= 5;

  _Pragma( "loopbound min 40 max 40" )
  for ( k = 0; k <= 39; k++ ) {

    L_result = 8192 >> 1;

#undef  STEP
#define STEP( i, H )  (e[  k + i  ] * (longword)H)

    #ifdef  STUPID_COMPILER
    L_result += STEP( 0,  -134 ) ;
    L_result += STEP( 1,  -374 )  ;

    L_result += STEP( 3,  2054 ) ;
    L_result += STEP( 4,  5741 ) ;
    L_result += STEP( 5,  8192 ) ;
    L_result += STEP( 6,  5741 ) ;
    L_result += STEP( 7,  2054 ) ;

    L_result += STEP( 9,  -374 ) ;
    L_result += STEP( 10,   -134 ) ;
    #else
    L_result +=
      STEP( 0,  -134 )
      + STEP( 1,  -374 )

      + STEP( 3,  2054 )
      + STEP( 4,  5741 )
      + STEP( 5,  8192 )
      + STEP( 6,  5741 )
      + STEP( 7,  2054 )

      + STEP( 9,  -374 )
      + STEP( 10,  -134 )
      ;
