void gsm_enc_APCM_quantization_xmaxc_to_exp_mant (
  word    xmaxc,
  word     *exp_out,
  word     *mant_out )
{
  word  exp, mant;

  exp = 0;
  if ( xmaxc > 15 ) exp = SASR( xmaxc, 3 ) - 1;
  mant = xmaxc - ( exp << 3 );

  if ( mant == 0 ) {
    exp  = -4;
    mant = 7;
  } else {
    _Pragma( "loopbound min 0 max 3" )
    while ( mant <= 7 ) {
      mant = mant << 1 | 1;
      exp--;
    }
    mant -= 8;
  }

  *exp_out  = exp;
  *mant_out = mant;

}

void gsm_enc_APCM_quantization (
  word     *xM,

  word     *xMc,
  word     *mant_out,
  word     *exp_out,
  word     *xmaxc_out
)
{
  int i, itest;

  word  xmax, xmaxc, temp, temp1, temp2;
  word  exp, mant;

  xmax = 0;

  _Pragma( "loopbound min 13 max 13" )
  for ( i = 0; i <= 12; i++ ) {
    temp = xM[ i ];
    temp = GSM_ABS( temp );
    if ( temp > xmax ) xmax = temp;
  }

  exp   = 0;
  temp  = SASR( xmax, 9 );
  itest = 0;

  _Pragma( "loopbound min 6 max 6" )
  for ( i = 0; i <= 5; i++ ) {

    itest |= ( temp <= 0 );
    temp = SASR( temp, 1 );

    if ( itest == 0 ) exp++;
  }

  temp = exp + 5;

  xmaxc = saturate( ( SASR( xmax, temp ) + ( exp << 3 ) ) );

  gsm_enc_APCM_quantization_xmaxc_to_exp_mant( xmaxc, &exp, &mant );

  temp1 = 6 - exp;
  temp2 = gsm_enc_NRFAC[  mant  ];

  _Pragma( "loopbound min 13 max 13" )
  for ( i = 0; i <= 12; i++ ) {

    temp = xM[ i ] << temp1;
    temp = GSM_MULT( temp, temp2 );
    temp = SASR( temp, 12 );
    xMc[ i ] = temp + 4;
  }

  *mant_out  = mant;
  *exp_out   = exp;
  *xmaxc_out = xmaxc;

}

void gsm_enc_APCM_inverse_quantization (
  word   *xMc,
  word    mant,
  word    exp,
  word   *xMp )

{
  int i;
  word  temp, temp1, temp2, temp3;
  longword  ltmp;

  temp1 = gsm_enc_FAC[  mant  ];
  temp2 = gsm_enc_sub( 6, exp );
  temp3 = gsm_enc_asl( 1, gsm_enc_sub( temp2, 1 ) );

  _Pragma( "loopbound min 13 max 13" )
  for ( i = 13; i--; ) {

    temp = ( *xMc++ << 1 ) - 7;

    temp <<= 12;
    temp = GSM_MULT_R( temp1, temp );
    temp = GSM_ADD( temp, temp3 );
    *xMp++ = gsm_enc_asr( temp, temp2 );
  }
}

void gsm_enc_RPE_grid_positioning (
  word    Mc,
  word   *xMp,
  word   *ep
)

{
  int i = 13;

  switch ( Mc ) {
    case 3:
      *ep++ = 0;
    case 2:
      *ep++ = 0;
    case 1:
      *ep++ = 0;
    case 0:
      *ep++ = *xMp++;
      i--;
  }

  _Pragma( "loopbound min 12 max 12" )
  do {
    *ep++ = 0;
    *ep++ = 0;
    *ep++ = *xMp++;
  } while ( --i );

  _Pragma( "loopbound min 0 max 3" )
  while ( ++Mc < 4 ) *ep++ = 0;

}

