void gsm_enc_Autocorrelation (
  word      *s,
  longword *L_ACF )

{
  int k, i;

  word    temp, smax, scalauto;

  smax = 0;

  _Pragma( "loopbound min 160 max 160" )
  for ( k = 0; k <= 159; k++ ) {
    temp = GSM_ABS( s[ k ] );
    if ( temp > smax ) smax = temp;
  }

  if ( smax == 0 ) scalauto = 0;
  else {
    scalauto = 4 - gsm_enc_norm( ( longword )smax << 16 );
