  if ( scalauto > 0 ) {

#   define SCALE(n) \
  case n: \
    _Pragma("loopbound min 160 max 160") \
    for (k = 0; k <= 159; k++) \
      s[ k ] = GSM_MULT_R( s[ k ], 16384 >> (n-1) );\
    break;

