  {
    word   *sp = s;
    word    sl = *sp;
#undef STEP
#   define STEP(k)   L_ACF[ k ] += ((longword)sl * sp[  -(k)  ]);

# define NEXTI   sl = *++sp

    _Pragma( "loopbound min 9 max 9" )
    for ( k = 9; k--; L_ACF[ k ] = 0 ) ;

    STEP ( 0 );
    NEXTI;
    STEP( 0 );
    STEP( 1 );
    NEXTI;
    STEP( 0 );
    STEP( 1 );
    STEP( 2 );
    NEXTI;
    STEP( 0 );
    STEP( 1 );
    STEP( 2 );
    STEP( 3 );
    NEXTI;
    STEP( 0 );
    STEP( 1 );
    STEP( 2 );
    STEP( 3 );
    STEP( 4 );
    NEXTI;
    STEP( 0 );
    STEP( 1 );
    STEP( 2 );
    STEP( 3 );
    STEP( 4 );
    STEP( 5 );
    NEXTI;
    STEP( 0 );
    STEP( 1 );
    STEP( 2 );
    STEP( 3 );
    STEP( 4 );
    STEP( 5 );
    STEP( 6 );
    NEXTI;
    STEP( 0 );
    STEP( 1 );
    STEP( 2 );
    STEP( 3 );
    STEP( 4 );
    STEP( 5 );
    STEP( 6 );
    STEP( 7 );

    _Pragma( "loopbound min 152 max 152" )
    for ( i = 8; i <= 159; i++ ) {

