void gsm_enc_Reflection_coefficients (
  longword   *L_ACF,
  word   *r
)
{
  int i, m, n;
  word  temp;
  longword ltmp;
  word    ACF[ 9 ];
  word    P[   9 ];
  word    K[   9 ];

  if ( L_ACF[ 0 ] == 0 ) {
    _Pragma( "loopbound min 8 max 8" )
    for ( i = 8; i--; *r++ = 0 ) ;
    return;
  }

  temp = gsm_enc_norm( L_ACF[ 0 ] );

  _Pragma( "loopbound min 9 max 9" )
  for ( i = 0; i <= 8; i++ ) ACF[ i ] = SASR( L_ACF[ i ] << temp, 16 );

  _Pragma( "loopbound min 7 max 7" )
  for ( i = 1; i <= 7; i++ ) K[  i  ] = ACF[  i  ];

  _Pragma( "loopbound min 9 max 9" )
  for ( i = 0; i <= 8; i++ ) P[  i  ] = ACF[  i  ];

  _Pragma( "loopbound min 8 max 8" )
  _Pragma( "marker outer-marker" )
  for ( n = 1; n <= 8; n++, r++ ) {

    temp = P[ 1 ];
    temp = GSM_ABS( temp );
    if ( P[ 0 ] < temp ) {

      _Pragma( "loopbound min 1 max 8" )
      for ( i = n; i <= 8; i++ ) *r++ = 0; _Pragma( "marker inner-marker" )
      return; _Pragma( "flowrestriction 1*inner-marker <= 36*outer-marker" )
    }

    *r = gsm_enc_div( temp, P[ 0 ] );

    if ( P[ 1 ] > 0 ) *r = -*r;
    if ( n == 8 ) return;

    temp = GSM_MULT_R( P[ 1 ], *r );
    P[ 0 ] = GSM_ADD( P[ 0 ], temp );

    _Pragma( "loopbound min 1 max 7" )
    for ( m = 1; m <= 8 - n; ++m ) {
      temp     = GSM_MULT_R( K[  m    ],    *r );
      P[ m ]     = GSM_ADD(    P[  m + 1  ],  temp );

      temp     = GSM_MULT_R( P[  m + 1  ],    *r );
      K[ m ]     = GSM_ADD(    K[  m    ],  temp );
    }
  }
}

void gsm_enc_Transformation_to_Log_Area_Ratios (
  word   *r
)

{
  word  temp;
  int i;

  _Pragma( "loopbound min 8 max 8" )
  for ( i = 1; i <= 8; i++, r++ ) {

    temp = *r;
    temp = GSM_ABS( temp );

    if ( temp < 22118 )
      temp >>= 1;

    else
      if ( temp < 31130 )
        temp -= 11059;

      else {
        temp -= 26112;
        temp <<= 2;
      }

    *r = *r < 0 ? -temp : temp;
  }
}

void gsm_enc_Quantization_and_coding (
  word *LAR
)
{
  word  temp;
  longword  ltmp;

# undef STEP
# define  STEP( A, B, MAC, MIC )    \
  temp = GSM_MULT( A,   *LAR ); \
  temp = GSM_ADD(  temp,   B ); \
  temp = GSM_ADD(  temp, 256 ); \
  temp = SASR(     temp,   9 ); \
  *LAR  =  temp>MAC ? MAC - MIC : (temp<MIC ? 0 : temp - MIC); \
  LAR++;

  STEP(  20480,     0,  31, -32 );
  STEP(  20480,     0,  31, -32 );
  STEP(  20480,  2048,  15, -16 );
  STEP(  20480, -2560,  15, -16 );

  STEP(  13964,    94,   7,  -8 );
  STEP(  15360, -1792,   7,  -8 );
  STEP(   8534,  -341,   3,  -4 );
  STEP(   9036, -1144,   3,  -4 );

# undef STEP
}

