    lsp = L_z2 - ( ( longword )msp << 15 );

    L_s2  += GSM_MULT_R( lsp, 32735 );
    L_temp = ( longword )msp * 32735;
    L_z2   = GSM_L_ADD( L_temp, L_s2 );

    L_temp = GSM_L_ADD( L_z2, 16384 );

    msp   = GSM_MULT_R( mp, -28180 );
    mp    = SASR( L_temp, 15 );
    *so++ = GSM_ADD( mp, msp );
  }

  S->z1   = z1;
  S->L_z2 = L_z2;
  S->mp   = mp;
}

word gsm_enc_norm ( longword a )

{
  if ( a < 0 ) {
    if ( a <= -1073741824 ) return 0;
    a = ~a;
  }

  return    a & 0xffff0000
            ? ( a & 0xff000000
                ?  -1 + gsm_enc_bitoff[  0xFF & ( a >> 24 )  ]
                :   7 + gsm_enc_bitoff[  0xFF & ( a >> 16 )  ] )
            : ( a & 0xff00
                ?  15 + gsm_enc_bitoff[  0xFF & ( a >> 8 )  ]
                :  23 + gsm_enc_bitoff[  0xFF & a  ] );
}

word gsm_enc_asl ( word a, int n )
{
  if ( n >= 16 ) return 0;
  if ( n <= -16 ) return -( a < 0 );
  if ( n < 0 ) return gsm_enc_asr( a, -n );
  return a << n;
}

word gsm_enc_asr ( word a, int n )
{
  if ( n >= 16 ) return -( a < 0 );
  if ( n <= -16 ) return 0;
  if ( n < 0 ) return a << -n;

  # ifdef SASR
  return a >> n;
  # else
  if ( a >= 0 ) return a >> n;
  else return -( word )( -( uword )a >> n );
  # endif
}

word gsm_enc_div ( word num, word denum )
{
  longword  L_num   = num;
  longword  L_denum = denum;
  word    div   = 0;
  int   k   = 15;

  if ( num == 0 )
    return 0;

  _Pragma( "loopbound min 15 max 15" )
  while ( k-- ) {
    div   <<= 1;
    L_num <<= 1;

    if ( L_num >= L_denum ) {
      L_num -= L_denum;
      div++;
    }
  }

  return div;
}

